def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    budget = float(my_status.get('budget', 0.0))
    hp = float(my_status.get('hp', 0.0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # If no opponents (edge case), bid enough to cover need but not overspend.
    if not alive_opponents:
        target = DAILY_SALARY * 0.45
        return min(budget, target)

    # React to yesterday's bids if available.
    yesterday_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            bid = prev.get('bid', None)
            if bid is not None:
                try:
                    yesterday_bids.append(float(bid))
                except Exception:
                    pass

    # Base aggressiveness depends on supply level: lower supply -> slightly higher bid.
    # Normalize supply to [0,1] where 0=MIN_SUPPLY, 1=MAX_SUPPLY.
    if MAX_SUPPLY > MIN_SUPPLY:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    # When supply is low (t small), bid multiplier increases.
    supply_multiplier = 0.55 + (1.0 - max(0.0, min(1.0, t))) * 0.25  # in [0.55,0.80]

    # If we see others bidding very high yesterday, we may need to match to avoid water starvation.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If they were near-salary, they likely are under pressure; bid more conservatively than them.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            base = DAILY_SALARY * 0.35
        elif highest_prev_bid >= DAILY_SALARY * 0.60:
            base = DAILY_SALARY * 0.45
        else:
            base = DAILY_SALARY * 0.40
    else:
        base = DAILY_SALARY * 0.42

    # HP-based adjustment: if low HP, bid up to protect survival.
    if hp <= 2:
        hp_multiplier = 1.25
    elif hp <= 4:
        hp_multiplier = 1.10
    else:
        hp_multiplier = 1.00

    bid = base * supply_multiplier * hp_multiplier

    # Ensure we don't overspend: cap at a fraction of budget.
    # Keep reserve to survive multiple days.
    reserve_fraction = 0.25 if hp > 3 else 0.15
    max_affordable = budget * (1.0 - reserve_fraction)

    # Also cap to not exceed a day-salary scale too aggressively.
    hard_cap = DAILY_SALARY * 0.95

    bid = min(bid, max_affordable, hard_cap)

    # Final safety: minimum bid if budget allows.
    if budget <= 0:
        return 0.0
    if bid < 0:
        bid = 0.0

    return float(bid)

