        urgent = 72
        if prev_bids:
            urgent = max(urgent, max(prev_bids) + 2)
        return min(budget, urgent)

    if scarcity <= 0:
        base = 28
    elif scarcity <= WATER_REQ:
        base = 42
    else:
        base = 56

    if desperate_opponents >= 2:
        base += 8
    elif desperate_opponents == 1:
        base += 4

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
        if highest_prev >= 80:
            base = min(base, 38 if hp >= 4 else 68)
