        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0

    bid = DAILY_SALARY * 0.45

    if my_status['hp'] <= 2:
        bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        bid = DAILY_SALARY * 0.75
    elif my_status['no_water_days'] >= 1:
        bid = DAILY_SALARY * 0.85

    current_supply = day_context['supply']
    total_water_needed_by_all = WATER_REQ + sum(o['water_requirement'] for o in alive_opponents)

    if current_supply < total_water_needed_by_all:
        if current_supply < WATER_REQ:
            bid = max(bid, DAILY_SALARY * 0.98)
        elif current_supply < WATER_REQ * 2:
            bid = max(bid, DAILY_SALARY * 0.85)
        else:
            bid = max(bid, DAILY_SALARY * 0.7)
    elif current_supply >= total_water_needed_by_all + WATER_REQ:
        bid = min(bid, DAILY_SALARY * 0.3)

    if highest_prev_bid > 0:
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            bid = max(bid, highest_prev_bid + 5)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            bid = max(bid, highest_prev_bid + 2)
        elif highest_prev_bid < DAILY_SALARY * 0.3 and my_status['hp'] > 4 and current_supply >= total_water_needed_by_all:
            bid = min(bid, highest_prev_bid + 1)

    current_day = day_context['day']
    if current_day > EPISODE_DAYS * 0.7:
        if my_status['hp'] > 5:
            bid = max(bid, DAILY_SALARY * 0.8)
        else:
            bid = max(bid, DAILY_SALARY * 0.9)
    elif current_day < EPISODE_DAYS * 0.3 and my_status['hp'] > 5 and current_supply >= total_water_needed_by_all:
        bid = min(bid, DAILY_SALARY * 0.4)

